import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { 
  FaArrowLeft, 
  FaMapMarkerAlt, 
  FaMapMarkedAlt,
  FaCar,
  FaSearchLocation
} from 'react-icons/fa';
import './SmartTourism.css';

// Nilgiris 6 Talukas data
const talukas = [
  {
    id: 1,
    name: 'Ooty',
    fullName: 'Udhagamandalam',
    image: 'https://images.unsplash.com/photo-1587474260584-136574528ed5?w=600',
    places: [
      { id: 1, name: 'Ooty Lake', type: 'Lake', rating: 4.5 },
      { id: 2, name: 'Botanical Garden', type: 'Garden', rating: 4.7 },
